template <mtpTypeId Type>
std::optional<RequestFields<Type>> ReadRequest(const mtpBuffer &body) {
	if (body.isEmpty() || uint32(body.front()) != Type) return std::nullopt;
	auto result = RequestFields<Type>();
	return result.read(body) ? std::optional(result) : std::nullopt;
}
